const rows = $input.all().map(item => item.json).filter(row => row?.product_id);
if (!rows.length) return [];

const now = new Date().toISOString();
const latestDate = rows
  .map(row => String(row.inventory_date).slice(0,10))
  .sort()
  .at(-1);

return [{
  json: {
    source: {
      key: "shopify",
      type: "commerce",
      displayName: "Shopify",
      metadata: {
        inventoryMode: "modeled_daily",
        inventorySourceTable: "shopify_product_inventory_daily"
      }
    },
    run: {
      key: `shopify-inventory-live-${latestDate}`,
      status: "success",
      startedAt: now,
      finishedAt: now,
      rowsRead: rows.length,
      rowsWritten: rows.length,
      rowsFailed: 0
    },
    metrics: [],
    products: [],
    inventory: rows.map(row => ({
      productKey: String(row.product_id),
      productName: String(row.product_name ?? row.product_id),
      capturedAt: `${String(row.inventory_date).slice(0,10)}T23:59:59.000Z`,
      available: row.available_quantity == null ? null : Number(row.available_quantity),
      metadata: {
        inventoryMode: "modeled_daily",
        sourceUpdatedAt: row.updated_at ?? null
      }
    })),
    records: []
  }
}];
